        tm = str(b.get('time') or '').strip()
        parts = tm.replace('.', ':').split(':')
        try:
            hh = int(parts[0])
            mm = int(parts[1]) if len(parts) > 1 and parts[1] else 0
            tm = '%02d:%02d' % (hh, mm)
